const entries = $input.all();
const rows = entries.flatMap(({ json }) => {
  if (Array.isArray(json)) return json;
  if (json && Array.isArray(json.body)) return json.body;
  if (json && Array.isArray(json.data)) return json.data;
  if (json && Array.isArray(json.items)) return json.items;
  return json && typeof json === 'object' ? [json] : [];
});
return rows
  .filter(row => row && (row.changeType === 'new' || row.changeType === 'changed'))
  .map(row => {
    const prefix = row.changeType === 'changed' ? 'Grant update' : 'New grant';
    const closing = row.closeDate || 'no close date published';
    return {
      json: {
        ...row,
        alertType: row.changeType === 'changed' ? 'grant_change' : 'grant_opportunity',
        alertText: `${prefix}: ${row.title} (${row.opportunityNumber}) - ${row.agency}; closes ${closing}\n${row.sourceUrl}`
      }
    };
  });
